/**
 * Template Bridge — words → gene-path distributions
 *
 * Source: PAradigm-reference/intelligence/template-bridge.md
 *
 * A "template" is a named recipe that declares which gene paths a
 * particular kind of seed needs, plus default values and sub-agent
 * weights. The Sovereign Agent uses templates to:
 *   - know which gene paths Stage 4 (assemble) should write to
 *   - know which sub-agents to consult in Stage 2 (resolve)
 *   - seed defaults when no sub-agent contributes a value
 *
 * Templates are immutable, deterministic, and ship as data — never
 * generated by the LLM. Adding a new domain = adding a new template.
 */

import type { TopLevelIntent } from './types';

export interface TemplatePath {
  path: string;
  /** Default value if no sub-agent contributes one. */
  default: number | string | number[] | string[];
  /** Which sub-agents are authoritative for this path. */
  authoritative: SubAgentName[];
  /** Optional gene-value range hint for validators. */
  range?: [number, number];
  /** Optional list of allowed string values. */
  enum?: string[];
}

export type SubAgentName =
  | 'VisionAgent'
  | 'PersonalityAgent'
  | 'MusicTheoryAgent'
  | 'NarrativeAgent'
  | 'MechanicsAgent'
  | 'PhysicsAgent'
  | 'StyleAgent'
  | 'CritiqueAgent';

export interface Template {
  id: string;
  domain: string;
  /** Top-level intents this template responds to. */
  intents: TopLevelIntent[];
  /** Sub-intents this template responds to. */
  subIntents: string[];
  /** Sub-agents to run (and their relative weight). */
  subAgents: Partial<Record<SubAgentName, number>>;
  /** Gene paths this template populates. */
  paths: TemplatePath[];
  /** Human-readable summary for prompts. */
  summary: string;
}

