const TEMPLATES_BY_ID: Map<string, Template> = new Map(TEMPLATES.map((t) => [t.id, t]));
const TEMPLATES_BY_DOMAIN: Map<string, Template> = new Map(TEMPLATES.map((t) => [t.domain, t]));

export function templateById(id: string): Template | undefined {
  return TEMPLATES_BY_ID.get(id);
}
export function templateForDomain(domain: string): Template | undefined {
  return TEMPLATES_BY_DOMAIN.get(domain);
}

/**
 * Pick the best template for a parsed intent.
 *
 * Scoring:
 *   +2 if the top-level intent matches
 *   +3 if any sub-intent matches the parsed sub-intent
 *   +1 for each domain string the parsed intent named that the template handles
 */
export function selectTemplate(
  top: TopLevelIntent,
  subIntent: string,
  domains: string[],
): Template {
  let best = TEMPLATES[0];
  let bestScore = -Infinity;
  for (const t of TEMPLATES) {
    let s = 0;
    if (t.intents.includes(top)) s += 2;
    if (t.subIntents.includes(subIntent)) s += 3;
    for (const d of domains) if (t.domain === d) s += 1;
    if (s > bestScore) {
      bestScore = s;
      best = t;
    }
  }
  return best;
}

/** All gene paths the template expects to populate. */
export function pathsFor(template: Template): string[] {
  return template.paths.map((p) => p.path);
}

/** Default-value lookup for a single gene path. */
export function defaultFor(template: Template, path: string): TemplatePath['default'] | undefined {
  return template.paths.find((p) => p.path === path)?.default;
}
